MATCH (a:Person {name: "Alice"}), (b:Person {name: "Bob"})
CALL gds.shortestPath.dijkstra.stream('socialGraph', {
    sourceNode: id(a),
    targetNode: id(b),
    relationshipWeightProperty: 'strength'
